{"term":"Dirne","lang":"de","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"archaic_prostitute","concept":"sex_worker_archaic","is_novel_concept":false,"register":"archaic","crude":30,"technical":20,"recognition_pct_current":60,"recognition_pct_peak":80,"peak_year":null,"regional":null,"definition":"An archaic term for a prostitute or young woman of loose morals; originally a neutral word for a girl or maidservant in Middle High German.","english_term":"strumpet","english_translation_quality":"approximate","notes":"Semantic narrowing over centuries from neutral 'girl/maid' to 'prostitute'; now primarily found in literature, history, and formal writing; still recognized but rarely used actively."}
{"term":"Metze","lang":"de","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"archaic_prostitute","concept":"sex_worker_archaic","is_novel_concept":false,"register":"archaic","crude":20,"technical":15,"recognition_pct_current":22,"recognition_pct_peak":55,"peak_year":null,"regional":null,"definition":"A very archaic word for a prostitute or loose woman; essentially obsolete in modern German.","english_term":"strumpet","english_translation_quality":"approximate","notes":"Medieval and Early Modern German term; nearly unintelligible to most modern speakers outside of historical literature; possibly derived from the female name Mechthild or Margarethe through hypocorism; peak use ca. 1300–1600."}
{"term":"Freudenmädchen","lang":"de","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"sex_worker_euphemism","concept":"sex_worker_archaic","is_novel_concept":false,"register":"euphemism","crude":20,"technical":15,"recognition_pct_current":75,"recognition_pct_peak":82,"peak_year":null,"regional":null,"definition":"'Joy girl'; a dated euphemism for a prostitute that softens the profession through pleasurable framing.","english_term":"joy girl","english_translation_quality":"approximate","notes":"Compound: 'Freuden' (joys/pleasures) + 'Mädchen' (girl); sounds antiquated or ironic today; widely recognized from historical texts, novels, and period-set films, but rarely used in contemporary speech."}
{"term":"Callgirl","lang":"de","script":"latin","romanization":null,"category":"sex_work_pornography","subcategory":"sex_worker","concept":"sex_worker","is_novel_concept":false,"register":"loanword","crude":30,"technical":20,"recognition_pct_current":95,"recognition_pct_peak":95,"peak_year":null,"regional":null,"definition":"A call girl; a female sex worker who takes appointments by phone or online, typically positioned as higher-end than street-based workers.","english_term":"call girl","english_translation_quality":"direct","notes":"Identical English loanword adopted without modification; implies discretion, scheduling, and a degree of social positioning above 'Nutte' or Straßenstrich workers; widely used in journalism and advertising."}
